package com.rikkeibank.transaction.domain;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="bank_transactions")public class BankTransaction{@Id private UUID id;@Column(nullable=false)private UUID sourceAccountId;@Column(nullable=false)private UUID targetAccountId;@Column(nullable=false)private UUID customerId;private UUID assignedTellerId;@Column(nullable=false,precision=19,scale=2)private BigDecimal amount;@Column(nullable=false)@Enumerated(EnumType.STRING)private Status status;private String failureReason;private Instant createdAt;private Instant completedAt;protected BankTransaction(){}public BankTransaction(UUID source,UUID target,UUID customer,BigDecimal amount){id=UUID.randomUUID();sourceAccountId=source;targetAccountId=target;customerId=customer;this.amount=amount;status=Status.PENDING;createdAt=Instant.now();}public void debited(){status=Status.DEBITED;}public void complete(){status=Status.COMPLETED;completedAt=Instant.now();}public void fail(String reason,boolean compensated){status=compensated?Status.COMPENSATED:Status.FAILED;failureReason=reason;completedAt=Instant.now();}public void assign(UUID id){assignedTellerId=id;}public UUID getId(){return id;}public UUID getSourceAccountId(){return sourceAccountId;}public UUID getTargetAccountId(){return targetAccountId;}public UUID getCustomerId(){return customerId;}public UUID getAssignedTellerId(){return assignedTellerId;}public BigDecimal getAmount(){return amount;}public Status getStatus(){return status;}public String getFailureReason(){return failureReason;}public Instant getCreatedAt(){return createdAt;}public Instant getCompletedAt(){return completedAt;}public enum Status{PENDING,DEBITED,COMPLETED,FAILED,COMPENSATED}}

